<script setup lang="ts">
import { onBeforeUnmount, onMounted, useTemplateRef } from "vue"; import { X } from "lucide-vue-next"; import type { CatalogoSistemaEstado,CatalogoSistemaUso } from "@/stores/dbequipos/engrase/catalogo/sistemasCatalogo.types";
defineProps<{open:boolean;estado:CatalogoSistemaEstado;uso:CatalogoSistemaUso;resultCount:number}>(); const emit=defineEmits<{close:[];reset:[];updateEstado:[value:CatalogoSistemaEstado];updateUso:[value:CatalogoSistemaUso]}>(); const panel=useTemplateRef<HTMLElement>("panel"); let previous:HTMLElement|null=null; let overflow="";
function keydown(e:KeyboardEvent){if(e.key==="Escape"){e.preventDefault();emit("close");return}if(e.key!=="Tab"||!panel.value)return;const controls=Array.from(panel.value.querySelectorAll<HTMLElement>("button,select"));const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
onMounted(()=>{previous=document.activeElement instanceof HTMLElement?document.activeElement:null;overflow=document.body.style.overflow;document.body.style.overflow="hidden";window.addEventListener("keydown",keydown);requestAnimationFrame(()=>panel.value?.querySelector<HTMLElement>("button")?.focus())});onBeforeUnmount(()=>{document.body.style.overflow=overflow;window.removeEventListener("keydown",keydown);previous?.focus()});
</script>
<template><Teleport to="body"><div v-if="open" class="fixed inset-0 z-[60] bg-main-dark/55" @click.self="emit('close')"><section ref="panel" role="dialog" aria-modal="true" aria-labelledby="systems-filters-title" class="absolute inset-x-0 bottom-0 rounded-t-xl bg-white"><header class="flex items-center justify-between border-b p-4"><h2 id="systems-filters-title" class="text-base font-bold text-main">Filtros</h2><button type="button" class="grid h-11 w-11 cursor-pointer place-items-center rounded-md" aria-label="Cerrar filtros" @click="emit('close')"><X class="h-4 w-4"/></button></header><div class="space-y-4 p-4"><label class="block text-xs font-semibold">Estado<select :value="estado" class="mt-1 min-h-11 w-full cursor-pointer rounded-md border px-3 text-base" @change="emit('updateEstado',($event.target as HTMLSelectElement).value as CatalogoSistemaEstado)"><option value="activos">Activos</option><option value="desactivados">Desactivados</option><option value="todos">Todos</option></select></label><label class="block text-xs font-semibold">En uso<select :value="uso" class="mt-1 min-h-11 w-full cursor-pointer rounded-md border px-3 text-base" @change="emit('updateUso',($event.target as HTMLSelectElement).value as CatalogoSistemaUso)"><option value="todos">Todos</option><option value="en-uso">En uso</option><option value="sin-uso">Sin uso</option></select></label></div><footer class="sticky bottom-0 grid grid-cols-2 gap-2 border-t bg-white p-4 pb-[max(1rem,env(safe-area-inset-bottom))]"><button type="button" class="min-h-11 cursor-pointer rounded-md border text-sm font-semibold" @click="emit('reset')">Restablecer</button><button type="button" class="min-h-11 cursor-pointer rounded-md bg-main px-3 text-sm font-semibold text-white" @click="emit('close')">Ver {{ new Intl.NumberFormat('es').format(resultCount) }} resultados</button></footer></section></div></Teleport></template>
